css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); }
.loader .bell { position: absolute; left: 16%; top: 12%; width: 68%; height: 60%; border-radius: 50% 50% 12% 12%; background: var(--loader-color); transform-origin: 50% 0; animation: twSwing calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader .bell::after { content: ''; position: absolute; left: -14%; bottom: -8%; width: 128%; height: 14%; border-radius: 9999px; background: var(--loader-color); }
.loader .clapper { position: absolute; left: 42%; bottom: 16%; width: 16%; height: 16%; border-radius: 9999px; background: var(--loader-secondary-color); animation: twClap calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
@keyframes twSwing { 0%, 100% { transform: rotate(-13deg); } 50% { transform: rotate(13deg); } }
@keyframes twClap { 0%, 100% { transform: translateX(-32%); } 50% { transform: translateX(32%); } }
